<?php
namespace App\Http\Controllers;
use App\Models\User; use App\Models\Grade; use App\Models\AcademicYear; use App\Models\Classroom; use App\Models\Semester;
class ReportController extends Controller {
 public function index(){ $u=auth()->user(); if($u->role==='siswa') return redirect()->route('reports.show',$u->id); if($u->role==='guru') $classes=Classroom::where('homeroom_teacher_id',$u->id)->with('students')->orderBy('name')->get(); else abort_unless(in_array($u->role,['admin','super_admin'],true),403); if(in_array($u->role,['admin','super_admin'],true)) $classes=Classroom::with('students')->orderBy('name')->get(); $years=AcademicYear::orderByDesc('id')->get(); $semesters=Semester::with('academicYear')->orderBy('id')->get(); return view('reports.index',compact('classes','years','semesters')); }
 public function classroom(Classroom $classroom){$u=auth()->user();abort_unless(in_array($u->role,['admin','super_admin'],true)||($u->role==='guru' && (int)$classroom->homeroom_teacher_id===(int)$u->id),403);$yearId=request('academic_year_id'); $semesterId=request('semester_id'); abort_unless($yearId && $semesterId, 422, 'Pilih tahun ajaran dan semester untuk mencetak rapor.'); $students=$classroom->students()->with(['studentGrades'=>fn($q)=>$q->where('status','published')->when($yearId,fn($x)=>$x->where('academic_year_id',$yearId))->when($semesterId,fn($x)=>$x->where('semester_id',$semesterId))->with(['subject','academicYear','semester'])])->orderBy('name')->get(); $cards=\App\Models\ReportCard::with(['academicYear','semester'])->where('classroom_id',$classroom->id)->where('status','approved')->when($yearId,fn($q)=>$q->where('academic_year_id',$yearId))->when($semesterId,fn($q)=>$q->where('semester_id',$semesterId))->get()->keyBy('student_id'); return view('reports.classroom',compact('classroom','students','cards','yearId','semesterId'));}
 public function show(User $student){$u=auth()->user();abort_unless($student->role==='siswa' && (in_array($u->role,['admin','super_admin'],true)||($u->role==='siswa' && $u->id===$student->id)),403);$grades=Grade::with(['subject','academicYear','semester'])->where('student_id',$student->id)->where('status','published')->orderBy('subject_id')->get();return view('reports.show',compact('student','grades'));}
}
